package com.restauranteAPI.restauranteAPI.service;
import com.restauranteAPI.restauranteAPI.model.*; import com.restauranteAPI.restauranteAPI.repository.*; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.util.*;
@Service public class RestauranteService { private final CategoriaRepository categorias; private final PratoRepository pratos; private final PedidoRepository pedidos; private final ItemPedidoRepository itens; public RestauranteService(CategoriaRepository c,PratoRepository p,PedidoRepository pe,ItemPedidoRepository i){categorias=c;pratos=p;pedidos=pe;itens=i;} public List<Categoria> categorias(){return categorias.findAll();} public Categoria categoria(Long id){return categorias.findById(id).orElseThrow();} public Categoria salvar(Categoria x){return categorias.save(x);} public void apagarCategoria(Long id){categorias.deleteById(id);} public List<Prato> pratos(){return pratos.findAll();} public List<Prato> disponiveis(){return pratos.findByDisponivelTrue();} public Prato prato(Long id){return pratos.findById(id).orElseThrow();} public Prato salvar(Prato x){ if(x.getCategoria()!=null && x.getCategoria().getId()!=null) x.setCategoria(categoria(x.getCategoria().getId())); return pratos.save(x); } public void apagarPrato(Long id){pratos.deleteById(id);} public List<Pedido> pedidos(){return pedidos.findAll();} public Pedido salvar(Pedido x){if(!x.getPrato().isDisponivel()) throw new IllegalStateException("Prato indisponivel"); x.setValorTotal(x.getPrato().getPreco().multiply(BigDecimal.valueOf(x.getQuantidade()))); return pedidos.save(x);} public Pedido pedido(Long id){return pedidos.findById(id).orElseThrow();} public void apagarPedido(Long id){pedidos.deleteById(id);} public List<ItemPedido> itens(){return itens.findAll();} public ItemPedido salvar(ItemPedido x){return itens.save(x);} public void apagarItem(Long id){itens.deleteById(id);} }

